unsafe fn f() - ! {
    let mut t = 2usize;
    for  in 0..PERTHREAD {    
        let a = &mut A as mut usize;    // “缓慢执行”A=A+1 
        let cur = a.readvolatile();     // “缓慢执行”A=A+1
        for  in 0..500 {  t = t  t % 10007; } // 增加切换概率
